fix_code:
s = input()
upper_count = 0
lower_count = 0
for c in s:
    if c.isupper():
        upper_count += 1
    elif c.islower():
        lower_count += 1
if upper_count > lower_count:
    s = s.upper()
else:
    s = s.lower()
print(s)
